{
  "name": "事件序列器",
  "name_en": "Event Sequencer",
  "manufacturer": "",
  "description": "事件序列器是一种实验时序控制设备，用于按预设顺序输出事件码或触发事件，以协调束线、探测器、电机或其他实验站设备的同步动作。它常用于加速器与同步辐射/自由电子激光实验中，实现扫描期间或采集过程中的精确定时控制。",
  "description_en": "An event sequencer is a timing control instrument that outputs programmed event codes or trigger events in a defined order to coordinate synchronized actions among beamline equipment, detectors, motors, or other experimental devices. It is commonly used in accelerator and photon-science experiments for precise timing control during scans and data acquisition.",
  "actions": [
    {
      "action_name": "auto-complete",
      "description": "完成当前事件序列运行并等待序列结束。",
      "description_en": "Complete the current event sequence run and wait for the sequence to finish."
    },
    {
      "action_name": "auto-kickoff",
      "description": "启动事件序列器并开始监测其运行状态。",
      "description_en": "Start the event sequencer and begin monitoring its running state."
    },
    {
      "action_name": "auto-pause",
      "description": "暂停当前事件序列运行。",
      "description_en": "Pause the current event sequence run."
    },
    {
      "action_name": "auto-resume",
      "description": "恢复已暂停的事件序列运行。",
      "description_en": "Resume a paused event sequence run."
    },
    {
      "action_name": "auto-start",
      "description": "启动事件序列器。",
      "description_en": "Start the event sequencer."
    },
    {
      "action_name": "auto-stop",
      "description": "停止事件序列器。",
      "description_en": "Stop the event sequencer."
    },
    {
      "action_name": "auto-trigger",
      "description": "触发事件序列器执行一次新的序列运行。",
      "description_en": "Trigger the event sequencer to execute a new sequence run."
    },
    {
      "action_name": "auto-get_seq",
      "description": "获取事件序列配置。",
      "description_en": "Get the event sequence configuration."
    },
    {
      "action_name": "auto-put_seq",
      "description": "设置事件序列配置。",
      "description_en": "Set the event sequence configuration."
    },
    {
      "action_name": "auto-show",
      "description": "显示当前事件序列内容。",
      "description_en": "Show the current event sequence contents."
    }
  ],
  "tag_hints": [
    "event sequencing",
    "timing control",
    "trigger generation",
    "beamline synchronization",
    "scan coordination",
    "accelerator timing"
  ]
}

